// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0); }
    function testRegression_property() public {
        // Owner calls AdjustBetAmounts(100) — the reference succeeds, bug reverts
        vm.prank(address(this));  // owner is the test contract
        try c.AdjustBetAmounts(100) {
            // reference: succeeds
            assertTrue(c.currentBetLimit() == 100);
        } catch {
            // bug: reverts; betLimit stays 0
            assertTrue(c.currentBetLimit() == 0);
        }
    }
}

