pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0); }
    function testRegression_property() public {
        // Since openToPublic defaults to false and only owner can change it, we need to call OpenToThePublic first
        // to observe the difference. In original, OpenToThePublic sets openToPublic = true.
        // In mutant, OpenToThePublic sets openToPublic = false.
        // We call AdjustBetAmounts (any amount) to satisfy the description that after AdjustBetAmounts the value differs.
        vm.prank(address(this)); // owner
        c.OpenToThePublic();
        vm.prank(address(this));
        c.AdjustBetAmounts(100); // any value works
        // After this sequence, original C has openToPublic == true, mutant has openToPublic == false
        bool isOpen = c.openToPublic();
        // Original holds true, mutant breaks (false)
        assertTrue(isOpen);
    }
}

