pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address alice = address(0x1234);

    function setUp() public { c = new C(address(this), 0); }

    function testRegression_property() public {
        // Step 1: Owner opens to public so wager() is callable
        vm.prank(address(this));
        c.OpenToThePublic();

        // Step 2: Set betLimit to 1 ether
        vm.prank(address(this));
        c.AdjustBetAmounts(1 ether);

        // Step 3: Give alice exactly 1 ether
        vm.deal(alice, 1 ether);

        // Step 4: Alice tries to wager (she has never wagered before, so wagers[alice] == 0)
        vm.prank(alice);
        // In reference: require(wagers[msg.sender] == 0) passes -> wager succeeds
        // In mutant: require(wagers[msg.sender] < 0) is false -> reverts
        // We capture success via try/catch
        bool success;
        try c.wager{value: 1 ether}() { success = true; } catch { success = false; }
        assertTrue(success); // reference passes, mutant fails (success false)
    }
}

