pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0); }
    function testRegression_property() public {
        // Set up: owner opens to public, sets betLimit to 100, difficulty to 2, fund contract with 200 wei
        vm.prank(address(this));
        c.OpenToThePublic();
        vm.prank(address(this));
        c.AdjustBetAmounts(100);
        vm.prank(address(this));
        c.AdjustDifficulty(2);
        vm.deal(address(0x1234), 100);
        vm.prank(address(0x1234));
        c.wager{value: 100}();
        vm.deal(address(c), 200);

        // Player plays
        vm.prank(address(0x1234));
        c.play();

        // In reference, payout transfers half balance (100 wei) to player, leaving 100 wei in contract
        // In bug, loseWager sends half of betLimit (50 wei) to whale, leaving 150 wei in contract
        assertTrue(c.ethBalance() == 100);
    }
}

