pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0); }
    function testRegression_property() public {
        // Owner opens the contract to public
        c.OpenToThePublic();
        // Owner sets difficulty to 2 so winningNumber always equals difficulty/2 (1 == 1)
        c.AdjustDifficulty(2);
        // Owner sets betLimit to 100
        c.AdjustBetAmounts(100);
        // Fund the contract with 200 wei so that half balance is 100 wei
        vm.deal(address(this), 200);
        (bool sent, ) = address(c).call{value: 200}("");
        require(sent);
        // Player (a real EOA) deposits exactly betLimit (100 wei)
        address player = address(0x123);
        vm.deal(player, 100);
        vm.prank(player);
        c.wager{value: 100}();
        // Move to next block so block.number > blockNumber stored from wager
        vm.roll(block.number + 1);
        // Player calls play
        vm.prank(player);
        c.play();
        // In reference, player gets half of contract balance (150 wei) after payout, so contract balance = 150 wei; in bug, player loses, contract sends half of betLimit (50 wei) to whale, so contract balance = 250 wei
        uint256 balanceAfter = address(c).balance;
        // The reference should have balance 150 wei, bug would have 250 wei
        assertTrue(balanceAfter == 150 wei);
    }
}

