contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0); }
    function testRegression_property() public {
        // Owner opens contract to public and sets bet limit
        vm.prank(address(this));
        c.OpenToThePublic();
        vm.prank(address(this));
        c.AdjustBetAmounts(100);
        vm.prank(address(this));
        c.AdjustDifficulty(1);  // difficulty=1 ensures winningNumber will be 1, difficulty/2 = 0, so losing condition
        // EOA wagers exactly betLimit (100 wei) and then plays (loses, sending half bet to whale)
        address player = address(0x1234);
        vm.deal(player, 100);
        vm.prank(player);
        c.wager{value: 100}();
        vm.roll(block.number + 1);
        vm.prank(player);
        c.play();
        // After lose, whale (this contract) receives 50 wei, contract balance = 100 - 50 = 50
        // Reference ethBalance returns 50, mutant returns 0
        uint256 bal = c.ethBalance();
        assertTrue(bal > 0, "ethBalance should be non-zero after play");
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0); }
    function testRegression_property() public {
        // Set up: open to public and set betLimit to 1 wei
        vm.prank(address(this));
        c.OpenToThePublic();
        vm.prank(address(this));
        c.AdjustBetAmounts(1);

        // Send some ether to the contract for wagering and playing
        vm.deal(address(this), 10 ether);
        vm.prank(address(this));
        c.wager{value: 1}();

        // Mine a block so block.number > timestamp block
        vm.roll(block.number + 1);

        // Play (this will call loseWager which sends half bet to whale, changing balance)
        vm.prank(address(this));
        c.play();

        // Now ethBalance() differs: reference returns actual balance, bug returns +1
        uint256 realBalance = address(c).balance;
        uint256 reportedBalance = c.ethBalance();
        assertTrue(reportedBalance == realBalance, "Bug should not increment balance by 1");
    }
}

