pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0); }
    function testRegression_property() public {
        // Open to public to enable donate
        c.OpenToThePublic();
        // Donate 1 wei to the contract
        vm.deal(address(this), 1);
        c.donate{value: 1}();
        // Now ethBalance() should be 1 for reference, but buggy returns 2
        assertTrue(c.ethBalance() == 1);
    }
}

